-- SATURN X | LOCAL COLA v1.0
-- Client-only bottle, procedural drinking pose, temporary local speed boost.
-- Simplified silhouette sampled from user-supplied coca_cola_bottle.glb.
-- Original model: MemoRorschach, CC BY 4.0.
-- https://sketchfab.com/3d-models/coca-cola-bottle-34075fedb0ef40d9a172231134849914
-- https://creativecommons.org/licenses/by/4.0/
-- Audio: exact user-supplied homemade_sfx-drink-swallow-272665.mp3.
-- Embedded media requires writefile + getcustomasset (or getsynasset).
-- Studio: optionally set SoundId and provide ReplicatedStorage.SaturnColaModel.
-- Speed can be overridden by the experience. No server/anti-cheat bypass.
local CONFIG = {Speed = 32, Duration = 15, DrinkTime = 2.40325, Cooldown = 3, SoundId = ""}
local AUDIO_B64 = ""
local LABEL_B64 = ""
local PROFILE = {1.2903,1.4103,1.5738,1.5809,1.557,1.4767,1.4106,1.3067,1.2955,1.3171,1.3447,1.386,1.4202,1.4535,1.491,1.537,1.5633,1.5183,1.3902,1.3902,1.3982,1.4009,1.4009,1.5166,1.5443,1.5438,1.4686,1.374,1.2364,1.1551,1.0202,0.9122,0.8291,0.7673,0.723,0.685,0.6719,0.7471,0.6744,0.6902}
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local SoundService = game:GetService("SoundService")
local ContentProvider = game:GetService("ContentProvider")
local UIS = game:GetService("UserInputService")
local player = Players.LocalPlayer
assert(player, "Run SATURN COLA on the Roblox client")
local playerGui = player:WaitForChild("PlayerGui")
local old = playerGui:FindFirstChild("SaturnColaLocal")
if old then
    local stop = old:FindFirstChild("Cleanup")
    if stop then stop:Fire() end
    old:Destroy()
end
local gui = Instance.new("ScreenGui")
gui.Name = "SaturnColaLocal"
gui.ResetOnSpawn = false
gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
gui.Parent = playerGui
local cleanupSignal = Instance.new("BindableEvent", gui)
cleanupSignal.Name = "Cleanup"
local panel = Instance.new("Frame", gui)
panel.Size = UDim2.fromOffset(218, 116)
panel.Position = UDim2.new(1, -230, 0, 55)
panel.BackgroundColor3 = Color3.fromRGB(20, 18, 28)
Instance.new("UICorner", panel).CornerRadius = UDim.new(0, 12)
local title = Instance.new("TextLabel", panel)
title.Size = UDim2.new(1, -30, 0, 28)
title.BackgroundTransparency = 1
title.Text = "SATURN X  |  COLA"
title.Font = Enum.Font.GothamBold
title.TextSize = 14
title.TextColor3 = Color3.fromRGB(232, 219, 255)
local close = Instance.new("TextButton", panel)
close.Size = UDim2.fromOffset(28, 28)
close.Position = UDim2.new(1, -28, 0, 0)
close.Text = "×"
close.TextSize = 22
close.BackgroundTransparency = 1
close.TextColor3 = Color3.new(1, 1, 1)
local status = Instance.new("TextLabel", panel)
status.Position = UDim2.fromOffset(8, 30)
status.Size = UDim2.new(1, -16, 0, 25)
status.BackgroundTransparency = 1
status.Text = "กำลังเตรียมเสียง..."
status.TextSize = 13
status.TextColor3 = Color3.new(1, 1, 1)
local button = Instance.new("TextButton", panel)
button.Position = UDim2.fromOffset(8, 60)
button.Size = UDim2.new(1, -16, 0, 33)
button.BackgroundColor3 = Color3.fromRGB(185, 26, 55)
button.Text = "หยิบขวด / Equip"
button.TextColor3 = Color3.new(1, 1, 1)
button.TextSize = 15
Instance.new("UICorner", button).CornerRadius = UDim.new(0, 8)
local audioLabel = Instance.new("TextLabel", panel)
audioLabel.Position = UDim2.fromOffset(6, 95)
audioLabel.Size = UDim2.new(1, -12, 0, 18)
audioLabel.BackgroundTransparency = 1
audioLabel.Text = "เสียง: กำลังโหลด"
audioLabel.TextColor3 = Color3.fromRGB(190, 180, 205)
audioLabel.TextSize = 10
local alive, character, humanoid, tool, bottle, sound = true, nil, nil, nil, nil, nil
local drinking, drinkStart, readyAt, boostUntil = false, 0, 0, 0
local shoulder, originalC0, baseSpeed, appliedSpeed
local connections, characterConnections = {}, {}
local pieces = {}
local generation = 0
local function connect(signal, fn, bucket)
    local c = signal:Connect(fn)
    table.insert(bucket or connections, c)
    return c
end
local function disconnect(bucket)
    for _, c in ipairs(bucket) do c:Disconnect() end
    table.clear(bucket)
end
local function restorePose()
    if shoulder and shoulder.Parent and originalC0 then shoulder.C0 = originalC0 end
    shoulder, originalC0 = nil, nil
end
local function restoreSpeed()
    if humanoid and humanoid.Parent and baseSpeed and appliedSpeed and math.abs(humanoid.WalkSpeed - appliedSpeed) < 0.01 then
        humanoid.WalkSpeed = baseSpeed
    end
    baseSpeed, appliedSpeed, boostUntil = nil, nil, 0
end
local function cancelDrink()
    drinking = false
    restorePose()
    if sound then sound:Stop() end
end
local function cleanupCharacter()
    generation = generation + 1
    cancelDrink()
    restoreSpeed()
    disconnect(characterConnections)
    if tool then tool:Destroy() end
    if bottle then bottle:Destroy() end
    tool, bottle, character, humanoid = nil, nil, nil, nil
    pieces = {}
    readyAt = 0
end
local function shutdown()
    if not alive then return end
    alive = false
    cleanupCharacter()
    disconnect(connections)
    if sound then sound:Destroy() end
    gui:Destroy()
end
connect(cleanupSignal.Event, shutdown)
connect(close.Activated, shutdown)
local function decode64(input)
    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local lookup, out, value, bits = {}, {}, 0, 0
    for i = 1, #alphabet do lookup[alphabet:sub(i, i)] = i - 1 end
    for i = 1, #input do
        local n = lookup[input:sub(i, i)]
        if n then
            value, bits = value * 64 + n, bits + 6
            if bits >= 8 then
                bits = bits - 8
                local divisor = 2 ^ bits
                out[#out + 1] = string.char(math.floor(value / divisor))
                value = value % divisor
            end
        end
    end
    return table.concat(out)
end
local customAsset = getcustomasset or getsynasset
local function saveAsset(filename, encoded)
    if type(writefile) ~= "function" or type(customAsset) ~= "function" then return nil end
    local ok, id = pcall(function()
        writefile(filename, decode64(encoded))
        return customAsset(filename)
    end)
    if ok then return id end
    return nil
end
local labelAsset
local function addCylinder(y, h, radius, color, transparency)
    local p = Instance.new("Part")
    p.Shape = Enum.PartType.Cylinder
    p.Size = Vector3.new(h, radius * 2, radius * 2)
    p.Color = color
    p.Transparency = transparency or 0
    p.Material = Enum.Material.SmoothPlastic
    p.Anchored, p.CanCollide, p.CanTouch, p.CanQuery = true, false, false, false
    p.CastShadow = false
    p.Parent = bottle
    table.insert(pieces, {p, CFrame.new(0, y, 0) * CFrame.Angles(0, 0, math.pi / 2), p.Transparency})
    return p
end
local function buildBottle()
    local supplied = game:GetService("ReplicatedStorage"):FindFirstChild("SaturnColaModel")
    if supplied and supplied:IsA("Model") and supplied:FindFirstChildWhichIsA("BasePart", true) then
        bottle = supplied:Clone()
        local _, size = bottle:GetBoundingBox()
        bottle:ScaleTo(bottle:GetScale() * 1.8 / math.max(size.Y, 0.01))
        local center = bottle:GetBoundingBox()
        for _, p in ipairs(bottle:GetDescendants()) do
            if p:IsA("BaseScript") then p:Destroy()
            elseif p:IsA("BasePart") then
                p.Anchored, p.CanCollide, p.CanTouch, p.CanQuery = true, false, false, false
                table.insert(pieces, {p, center:ToObjectSpace(p.CFrame), p.Transparency})
            end
        end
    else
        bottle = Instance.new("Model")
        local scale = 1.8 / 10.28
        for i, radius in ipairs(PROFILE) do
            local y = ((i - 0.5) * 10.28 / #PROFILE - 5.14) * scale
            addCylinder(y, 1.8 / #PROFILE + 0.006, radius * scale, Color3.fromRGB(45, 18, 13), 0.08)
        end
        addCylinder(0.9, 0.065, 0.139, Color3.fromRGB(204, 28, 40))
        addCylinder(0.034, 0.32, 0.275, Color3.fromRGB(205, 23, 38))
        local face = Instance.new("Part", bottle)
        face.Size = Vector3.new(0.55, 0.32, 0.55)
        face.Anchored, face.CanCollide, face.CanTouch, face.CanQuery = true, false, false, false
        face.Transparency = 1
        table.insert(pieces, {face, CFrame.new(0, 0.034, 0), 1})
        for _, side in ipairs({Enum.NormalId.Front, Enum.NormalId.Back}) do
            local surface = Instance.new("SurfaceGui", face)
            surface.Face, surface.CanvasSize = side, Vector2.new(512, 256)
            surface.LightInfluence = 0
            if labelAsset then
                local img = Instance.new("ImageLabel", surface)
                img.Size, img.BackgroundTransparency, img.Image = UDim2.fromScale(1, 1), 1, labelAsset
            else
                local text = Instance.new("TextLabel", surface)
                text.Size, text.BackgroundTransparency = UDim2.fromScale(1, 1), 1
                text.Text, text.TextScaled, text.TextColor3 = "Coca-Cola", true, Color3.new(1, 1, 1)
                text.Font = Enum.Font.SourceSansItalic
            end
        end
    end
    bottle.Name = "SaturnCola_ClientOnly"
    -- Keep unparented until equipped, so it cannot flash at the world origin.
end
local function drink()
    if not alive or not humanoid or humanoid.Health <= 0 or not tool or tool.Parent ~= character then return end
    if drinking or os.clock() < readyAt or os.clock() < boostUntil then return end
    drinking, drinkStart = true, os.clock()
    local torso = character:FindFirstChild("UpperTorso") or character:FindFirstChild("Torso")
    shoulder = character:FindFirstChild("RightShoulder", true) or (torso and torso:FindFirstChild("Right Shoulder"))
    if shoulder then originalC0 = shoulder.C0 end
    if sound and sound.IsLoaded then sound.TimePosition = 0; sound:Play() end
end
local function equipOrDrink()
    if tool and humanoid and humanoid.Health > 0 then
        if tool.Parent ~= character then humanoid:EquipTool(tool) else drink() end
    end
end
connect(button.Activated, equipOrDrink)
connect(UIS.InputBegan, function(input, processed)
    if not processed and input.KeyCode == Enum.KeyCode.F5 then equipOrDrink() end
end)
local function setup(newCharacter)
    if not alive then return end
    cleanupCharacter()
    character = newCharacter
    local token = generation
    local h = newCharacter:WaitForChild("Humanoid", 10)
    local backpack = player:WaitForChild("Backpack", 10)
    if not alive or token ~= generation or not h or not backpack then return end
    humanoid = h
    buildBottle()
    tool = Instance.new("Tool")
    tool.Name, tool.ToolTip = "SATURN COLA", "ดื่มแล้ววิ่งเร็วขึ้น 15 วินาที"
    tool.RequiresHandle, tool.CanBeDropped = false, false
    connect(tool.Activated, drink, characterConnections)
    connect(tool.Unequipped, cancelDrink, characterConnections)
    connect(h.Died, function() cancelDrink(); restoreSpeed(); if bottle then bottle.Parent = nil end end, characterConnections)
    tool.Parent = backpack
end
connect(player.CharacterAdded, function(c) task.spawn(setup, c) end)
connect(player.CharacterRemoving, function(c) if c == character then cleanupCharacter() end end)
connect(RunService.RenderStepped, function()
    local now = os.clock()
    if boostUntil > 0 and now >= boostUntil then restoreSpeed() end
    if not tool or not character or not humanoid then status.Text = "รอตัวละคร..."; return end
    local equipped = tool.Parent == character and humanoid.Health > 0
    button.Text = equipped and "ดื่ม / Drink" or "หยิบขวด / Equip"
    if drinking then status.Text = "กำลังดื่ม..."
    elseif boostUntil > now then status.Text = "บูสต์เหลือ " .. math.ceil(boostUntil - now) .. " วินาที"
    elseif readyAt > now then status.Text = "พัก " .. math.ceil(readyAt - now) .. " วินาที"
    else status.Text = "พร้อม • ความเร็ว " .. CONFIG.Speed end
    if not equipped then
        if drinking then cancelDrink() end
        if bottle then bottle.Parent = nil end
        return
    end
    local hand = character:FindFirstChild("RightHand") or character:FindFirstChild("Right Arm")
    local head = character:FindFirstChild("Head")
    if not hand or not head then return end
    local base = hand.CFrame * CFrame.new(0, -0.1, -0.38)
    if drinking then
        local elapsed = now - drinkStart
        local amount = math.min(elapsed / 0.4, 1, math.max(0, (CONFIG.DrinkTime - elapsed) / 0.35))
        amount = amount * amount * (3 - 2 * amount)
        if shoulder and originalC0 then shoulder.C0 = originalC0 * CFrame.Angles(math.rad(-95) * amount, 0, math.rad(12) * amount) end
        local target = head.CFrame * CFrame.new(0.25, -0.32, -0.7) * CFrame.Angles(math.rad(-105), 0, 0) * CFrame.new(0, -0.9, 0)
        base = base:Lerp(target, amount)
        if elapsed >= CONFIG.DrinkTime then
            cancelDrink()
            baseSpeed = humanoid.WalkSpeed
            appliedSpeed = math.max(baseSpeed, CONFIG.Speed)
            humanoid.WalkSpeed = appliedSpeed
            boostUntil = now + CONFIG.Duration
            readyAt = boostUntil + CONFIG.Cooldown
        end
    end
    for _, entry in ipairs(pieces) do entry[1].CFrame = base * entry[2] end
    bottle.Parent = workspace.CurrentCamera
end)
task.spawn(function()
    labelAsset = saveAsset("saturn_cola_label_v1.jpg", LABEL_B64)
    local id = CONFIG.SoundId ~= "" and CONFIG.SoundId or saveAsset("saturn_cola_drink_v1.mp3", AUDIO_B64)
    if not alive then return end
    if id then
        sound = Instance.new("Sound")
        sound.Name, sound.SoundId, sound.Volume = "SaturnCola_LocalDrink", id, 0.8
        sound.Parent = SoundService
        task.spawn(function()
            pcall(function() ContentProvider:PreloadAsync({sound}) end)
            if alive then audioLabel.Text = sound.IsLoaded and "เสียงดื่ม: พร้อม" or "เสียงโหลดไม่ได้ • ตรวจ custom asset" end
        end)
        task.delay(10, function()
            if alive and sound and not sound.IsLoaded then audioLabel.Text = "เสียงโหลดไม่ได้ • ตรวจ custom asset" end
        end)
    else
        audioLabel.Text = "ตัวรันไม่รองรับเสียงไฟล์ • ตั้ง SoundId ได้"
    end
    if player.Character and not character then setup(player.Character) end
end)
